#include <stdio.h>

typedef struct { const char *name; double arrival; double service; } Job;

/* 返回平均周转时间，并通过指针输出带权与等待的平均值 */
double solve(const Job *jobs, int n,
             double *avg_weighted, double *avg_waiting) {
    double t = 0.0;
    double sum_turn = 0.0, sum_weighted = 0.0, sum_wait = 0.0;

    for (int i = 0; i < n; ++i) {
        double arrival = jobs[i].arrival;
        double service = jobs[i].service;

        double start  = (t > arrival) ? t : arrival;   /* max(t, arrival) */
        double finish = start + service;
        double turnaround = finish - arrival;

        sum_turn     += turnaround;
        sum_weighted += turnaround / service;
        sum_wait     += turnaround - service;

        t = finish;
    }

    *avg_weighted = sum_weighted / n;
    *avg_waiting  = sum_wait / n;
    return sum_turn / n;
}
